module triple_correlation #(\n    parameter P_MAX = 20,\n    parameter N_MAX = 3,\n    parameter M_MAX = 3\n)(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] p,\n    input wire [3:0] seq [0:P_MAX-1],\n    output reg found,\n    output reg [3:0] a_out,\n    output reg [3:0] b_out,\n    output reg [3:0] c_out,\n    output reg [7:0] n_out,\n    output reg [7:0] m_out,\n    output reg done\n);\n\n    // Internal registers\n    reg [3:0] seq_reg [0:P_MAX-1];\n    reg [7:0] p_reg;\n    reg [7:0] T;\n    reg [7:0] n_reg, m_reg;\n    reg [3:0] a_reg, b_reg, c_reg;\n    reg [7:0] i;\n    reg [7:0] triple_count;\n    reg [7:0] first_i;\n    reg candidate_valid;\n    reg [3:0] best_a, best_b, best_c;\n    reg [7:0] best_n, best_m, best_first_i;\n\n    // State definition\n    localparam [3:0] IDLE = 4'd0;\n    localparam [3:0] LOAD = 4'd1;\n    localparam [3:0] SEARCH = 4'd2;\n    localparam [3:0] SCANNING = 4'd3;\n    localparam [3:0] EVALUATE = 4'd4;\n    localparam [3:0] NEXT_C = 4'd5;\n    localparam [3:0] NEXT_B = 4'd6;\n    localparam [3:0] NEXT_A = 4'd7;\n    localparam [3:0] NEXT_M = 4'd8;\n    localparam [3:0] NEXT_N = 4'd9;\n    localparam [3:0] DONE = 4'd10;\n    reg [3:0] state;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            found <= 1'b0;\n            p_reg <= 8'd0;\n            T <= 8'd0;\n            n_reg <= 8'd0;\n            m_reg <= 8'd0;\n            a_reg <= 4'd0;\n            b_reg <= 4'd0;\n            c_reg <= 4'd0;\n            i <= 8'd0;\n            triple_count <= 8'd0;\n            first_i <= 8'd0;\n            candidate_valid <= 1'b0;\n            best_a <= 4'd0;\n            best_b <= 4'd0;\n            best_c <= 4'd0;\n            best_n <= 8'd0;\n            best_m <= 8'd0;\n            best_first_i <= 8'd0;\n            integer idx;\n            for (idx = 0; idx < P_MAX; idx = idx + 1) begin\n                seq_reg[idx] <= 4'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= LOAD;\n                    end\n                end\n                LOAD: begin\n                    integer idx;\n                    for (idx = 0; idx < P_MAX; idx = idx + 1) begin\n                        seq_reg[idx] <= seq[idx];\n                    end\n                    p_reg <= p;\n                    T <= (p_reg + 8'd39) / 8'd40 + 8'd1;\n                    best_first_i <= 8'd255;\n                    found <= 1'b0;\n                    state <= SEARCH;\n                end\n                SEARCH: begin\n                    n_reg <= 8'd1;\n                    m_reg <= 8'd1;\n                    a_reg <= 4'd0;\n                    b_reg <= 4'd0;\n                    c_reg <= 4'd0;\n                    state <= SCANNING;\n                    i <= 8'd0;\n                    triple_count <= 8'd0;\n                    first_i <= 8'd255;\n                    candidate_valid <= 1'b1;\n                end\n                SCANNING: begin\n                    if (i < p_reg) begin\n                        if ( (\n                             (seq_reg[i] == a_reg && i + n_reg < p_reg && seq_reg[i + n_reg] == b_reg && i + n_reg + m_reg < p_reg && seq_reg[i + n_reg + m_reg] != c_reg) ||\n                             (seq_reg[i] == b_reg && i + m_reg < p_reg && seq_reg[i + m_reg] == c_reg && i >= n_reg && seq_reg[i - n_reg] != a_reg) ||\n                             (seq_reg[i] == a_reg && i + n_reg + m_reg < p_reg && seq_reg[i + n_reg + m_reg] == c_reg && i + n_reg < p_reg && seq_reg[i + n_reg] != b_reg)\n                           ) ) begin\n                            candidate_valid <= 1'b0;\n                            state <= NEXT_C;\n                        end else begin\n                            if (i + n_reg < p_reg && i + n_reg + m_reg < p_reg &&\n                                seq_reg[i] == a_reg && seq_reg[i + n_reg] == b_reg && seq_reg[i + n_reg + m_reg] == c_reg) begin\n                                triple_count <= triple_count + 8'd1;\n                                if (first_i > 8'd254) first_i <= i;\n                            end\n                            i <= i + 8'd1;\n                            if (i + 8'd1 < p_reg) begin\n                                state <= SCANNING;\n                            end else begin\n                                state <= EVALUATE;\n                            end\n                        end\n                    end else begin\n                        state <= EVALUATE;\n                    end\n                end\n                EVALUATE: begin\n                    if (candidate_valid && triple_count >= T) begin\n                        if (first_i < best_first_i ||\n                            (first_i == best_first_i && n_reg < best_n) ||\n                            (first_i == best_first_i && n_reg == best_n && m_reg < best_m)) begin\n                            best_a <= a_reg;\n                            best_b <= b_reg;\n                            best_c <= c_reg;\n                            best_n <= n_reg;\n                            best_m <= m_reg;\n                            best_first_i <= first_i;\n                        end\n                    end\n                    state <= NEXT_C;\n                end\n                NEXT_C: begin\n                    if (c_reg == 4'd9) begin\n                        state <= NEXT_B;\n                    end else begin\n                        c_reg <= c_reg + 4'd1;\n                        state <= SCANNING;\n                        i <= 8'd0;\n                        triple_count <= 8'd0;\n                        first_i <= 8'd255;\n                        candidate_valid <= 1'b1;\n                    end\n                end\n                NEXT_B: begin\n                    if (b_reg == 4'd9) begin\n                        state <= NEXT_A;\n                    end else begin\n                        b_reg <= b_reg + 4'd1;\n                        c_reg <= 4'd0;\n                        state <= SCANNING;\n                        i <= 8'd0;\n                        triple_count <= 8'd0;\n                        first_i <= 8'd255;\n                        candidate_valid <= 1'b1;\n                    end\n                end\n                NEXT_A: begin\n                    if (a_reg == 4'd9) begin\n                        state <= NEXT_M;\n                    end else begin\n                        a_reg <= a_reg + 4'd1;\n                        b_reg <= 4'd0;\n                        c_reg <= 4'd0;\n                        state <= SCANNING;\n                        i <= 8'd0;\n                        triple_count <= 8'd0;\n                        first_i <= 8'd255;\n                        candidate_valid <= 1'b1;\n                    end\n                end\n                NEXT_M: begin\n                    if (m_reg == M_MAX) begin\n                        state <= NEXT_N;\n                    end else begin\n                        m_reg <= m_reg + 8'd1;\n                        a_reg <= 4'd0;\n                        b_reg <= 4'd0;\n                        c_reg <= 4'd0;\n                        state <= SCANNING;\n                        i <= 8'd0;\n                        triple_count <= 8'd0;\n                        first_i <= 8'd255;\n                        candidate_valid <= 1'b1;\n                    end\n                end\n                NEXT_N: begin\n                    if (n_reg == N_MAX) begin\n                        state <= DONE;\n                    end else begin\n                        n_reg <= n_reg + 8'd1;\n                        m_reg <= 8'd1;\n                        a_reg <= 4'd0;\n                        b_reg <= 4'd0;\n                        c_reg <= 4'd0;\n                        state <= SCANNING;\n                        i <= 8'd0;\n                        triple_count <= 8'd0;\n                        first_i <= 8'd255;\n                        candidate_valid <= 1'b1;\n                    end\n                end\n                DONE: begin\n                    done <= 1'b1;\n                    if (best_first_i < 8'd255) begin\n                        found <= 1'b1;\n                        a_out <= best_a;\n                        b_out <= best_b;\n                        c_out <= best_c;\n                        n_out <= best_n;\n                        m_out <= best_m;\n                    end else begin\n                        found <= 1'b0;\n                    end\n                    state <= IDLE;\n                end\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule